WITH unpivoted AS (SELECT * FROM (SELECT id, store_id, amount, discount, shipping_fee FROM orders) src UNPIVOT INCLUDE NULLS (metric_value FOR measure IN (amount AS AMOUNT, discount, shipping_fee AS SHIPPING_FEE_VAL))) SELECT CASE WHEN metric_value >= 62 THEN 'LARGE' ELSE 'SMALL' END AS metric_value_tier, MAX(metric_value) AS max_metric_value, SUM(CASE WHEN measure = 'discount' THEN metric_value ELSE 0 END) AS discount_metric_value, SIZE(COLLECT_SET(measure)) AS num_measures FROM unpivoted GROUP BY CASE WHEN metric_value >= 62 THEN 'LARGE' ELSE 'SMALL' END
